import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"7、【师】 坎下坤上","description":"周易口诀义 - 7、【师】 坎下坤上","frontmatter":{"title":"7、【师】 坎下坤上","description":"周易口诀义 - 7、【师】 坎下坤上"},"headers":[],"relativePath":"zh/classics/koujueyi/009.md","filePath":"zh/classics/koujueyi/009.md"}'),r={name:"zh/classics/koujueyi/009.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_7、【师】-坎下坤上" tabindex="-1">7、【师】 坎下坤上 <a class="header-anchor" href="#_7、【师】-坎下坤上" aria-label="Permalink to “7、【师】 坎下坤上”">​</a></h1><p>彖曰：师，众也；贞，正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒天下而民从之，吉又何咎矣！</p><p>象曰：地中有水，「师」，君子以容民畜众。</p><p>初六：师出以律，否臧凶。</p><p>象曰：「师出以律」，失律凶也。</p><p>九二：在师中吉，无咎。王三锡命。</p><p>象曰：「在师中吉」，承天宠也。「王三锡命」，怀万邦也。</p><p>六三：师或舆尸，凶。</p><p>象曰：「师或舆尸」，大无功也。</p><p>六四：师左次，无咎。</p><p>象曰：「左次无咎」，未失常也。</p><p>六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。</p><p>象曰：「长子帅师」，以中行也。「弟子舆尸」，使不当也。</p><p>上六：大君有命，开国承家，小人勿用。</p><p>象曰：「大君有命」，以正功也。「小人勿用」，必乱邦也。</p><p>解读</p><p>「师贞丈人吉无咎」者，师者，众也，军旅之名，法长之义，故陆绩云「师为众首，法长而行」是也。以师为正，故曰</p><p>「师」。贞丈人吉无咎者，丈人谓严毅德长之人，可以监临于众，故曰「丈人」也。夫兴师征伐，必须有功劳，即无罪咎，故曰「吉，无咎」也。</p><p>象曰「地中有水，师，君子以容民畜众」者，缘地能包水，亦犹为师之主，容纳于民也。君子为众之长，当含小过，不尚绝严，容纳民人，畜聚于众也。</p><p>「初六，师出以律，否臧，凶」者，律，法也；否，破败也；臧，有功也。初六为师之首，必须齐整师旅，而不失法律者也。若其失律违法，虽见获功，徒劳而已，故否之与臧，皆见凶也。</p><p>九二，在师中，吉，无咎。「王三锡命」者，九二以刚德处中，为君委任，故曰「在师中」也。既为君所任，任大役重，必须有功，无功即凶，故曰「吉，无咎」也。吉者，有功之辞也。「王三锡命」者，以其能招万邦而有功，故君王三度锡赐其命。</p><p>「六三，师或舆尸，凶」者，六三体质柔弱，而复乘刚，又无应援，若使之行师，必见丧败，故曰舆尸而归，「凶」也。</p><p>「六四，师左次，无咎」者，以阴得位而无其应，无应即不可征伐也，得位则可以自处也。夫为帅众而处，必须量其便宜，取其右背山陵，前左水泽，而次止之，则「无咎」也。又云：「左是偏将处之，右是上将，有主死之权也。</p><p>六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶」者，以柔处尊，不先威猛，只是物来先犯者也。犹如田之苗稼为禽所犯，故用执之言语，问其情诛，亦无咎。故曰：「田有禽，利执言，无咎。」六五体既柔弱，不可自行攻伐，故任用长子帅领师众也。若任之弟子，则致「舆尸」之凶。故庄氏云：「长子谓九二，德长于人也；弟子谓六三，德劣于物也。」</p><p>「上六：大君有命，开国承家，小人勿用」者，上六处师之极，即是有功之人。既有功劳，即天子锡之爵命矣。若其功大，开国为诸侯；若其功小，使之承家为卿大夫也。若山入有功，但锡之金帛，不可任之以位，故勿用小人，必乱邦也。「大君」为天子，亦喻大人有天命，用之开国。小人无命，止于为盗。</p>',25)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
